css:
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0
}

.relative {
  position: relative
}

.inline-flex {
  display: inline-flex
}

.h-8 {
  height: 2rem
}

.w-20 {
  width: 5rem
}

.cursor-pointer {
  cursor: pointer
}

.items-center {
  align-items: center
}

.rounded-full {
  border-radius: 9999px
}

.bg-gradient-to-r {
  background-image: linear-gradient(to right, var(--tw-gradient-stops))
}

.from-rose-400 {
  --tw-gradient-from: #fb7185 var(--tw-gradient-from-position);
  --tw-gradient-to: rgb(251 113 133 / 0) var(--tw-gradient-to-position);
  --tw-gradient-stops: var(--tw-gradient-from), var(--tw-gradient-to)
}

.to-red-900 {
  --tw-gradient-to: #7f1d1d var(--tw-gradient-to-position)
}

.shadow-inner {
  --tw-shadow: inset 0 2px 4px 0 rgb(0 0 0 / 0.05);
  --tw-shadow-colored: inset 0 2px 4px 0 var(--tw-shadow-color);
  box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow)
}

.shadow-gray-900 {
  --tw-shadow-color: #111827;
  --tw-shadow: var(--tw-shadow-colored)
}

.outline-none {
  outline: 2px solid transparent;
  outline-offset: 2px
}

.ring-2 {
  --tw-ring-offset-shadow: var(--tw-ring-inset) 0 0 0 var(--tw-ring-offset-width) var(--tw-ring-offset-color);
  --tw-ring-shadow: var(--tw-ring-inset) 0 0 0 calc(2px + var(--tw-ring-offset-width)) var(--tw-ring-color);
  box-shadow: var(--tw-ring-offset-shadow), var(--tw-ring-shadow), var(--tw-shadow, 0 0 #0000)
}

.ring-gray-900 {
  --tw-ring-opacity: 1;
  --tw-ring-color: rgb(17 24 39 / var(--tw-ring-opacity))
}

.duration-300 {
  transition-duration: 300ms
}

.after\:absolute::after {
  content: var(--tw-content);
  position: absolute
}

.after\:-left-2::after {
  content: var(--tw-content);
  left: -0.5rem
}

.after\:-top-2::after {
  content: var(--tw-content);
  top: -0.5rem
}

.after\:flex::after {
  content: var(--tw-content);
  display: flex
}

.after\:h-12::after {
  content: var(--tw-content);
  height: 3rem
}

.after\:w-12::after {
  content: var(--tw-content);
  width: 3rem
}

.after\:items-center::after {
  content: var(--tw-content);
  align-items: center
}

.after\:justify-center::after {
  content: var(--tw-content);
  justify-content: center
}

.after\:rounded-full::after {
  content: var(--tw-content);
  border-radius: 9999px
}

.after\:border-4::after {
  content: var(--tw-content);
  border-width: 4px
}

.after\:border-gray-900::after {
  content: var(--tw-content);
  --tw-border-opacity: 1;
  border-color: rgb(17 24 39 / var(--tw-border-opacity))
}

.after\:bg-gray-50::after {
  content: var(--tw-content);
  --tw-bg-opacity: 1;
  background-color: rgb(249 250 251 / var(--tw-bg-opacity))
}

.after\:outline-none::after {
  content: var(--tw-content);
  outline: 2px solid transparent;
  outline-offset: 2px
}

.after\:duration-500::after {
  content: var(--tw-content);
  transition-duration: 500ms
}

